bool loadShaderSources(){
    auto root=assetRoot.parent_path();
    std::ifstream vertex(root/"shaders/vertex.glsl"),fragment(root/"shaders/fragment.glsl");
    if(!vertex||!fragment){std::cerr<<"Shader file load failed under "<<(root/"shaders")<<'\n';return false;}
    std::ostringstream v,f;v<<vertex.rdbuf();f<<fragment.rdbuf();vertexShaderSource=v.str();fragmentShaderSource=f.str();
    return !vertexShaderSource.empty()&&!fragmentShaderSource.empty();
}
