void makeCube(){float n=-.5f,p=.5f;face({n,n,p},{p,n,p},{p,p,p},{n,p,p},{1,1,1});face({p,n,n},{n,n,n},{n,p,n},{p,p,n},{.84f,.84f,.84f});face({n,n,n},{n,n,p},{n,p,p},{n,p,n},{.75f,.75f,.75f});face({p,n,p},{p,n,n},{p,p,n},{p,p,p},{.9f,.9f,.9f});face({n,p,p},{p,p,p},{p,p,n},{n,p,n},{1,1,1});face({n,n,n},{p,n,n},{p,n,p},{n,n,p},{.65f,.65f,.65f});}
void makeSphere(){const int rings=12,sectors=18;for(int r=0;r<rings;r++)for(int s=0;s<sectors;s++){float a0=glm::pi<float>()*r/rings,a1=glm::pi<float>()*(r+1)/rings,b0=glm::two_pi<float>()*s/sectors,b1=glm::two_pi<float>()*(s+1)/sectors;auto point=[](float a,float b){return glm::vec3(std::sin(a)*std::cos(b),std::cos(a),std::sin(a)*std::sin(b))*.5f;};glm::vec3 p0=point(a0,b0),p1=point(a1,b0),p2=point(a1,b1),p3=point(a0,b1);for(auto p:{p0,p1,p2,p0,p2,p3})sphereMesh.push_back({p,{1,1,1},glm::normalize(p)});}}
void initGL(){makeCube();makeSphere();auto configure=[](GLuint& a,GLuint& b,const std::vector<V>& mesh){glGenVertexArrays(1,&a);glGenBuffers(1,&b);glBindVertexArray(a);glBindBuffer(GL_ARRAY_BUFFER,b);glBufferData(GL_ARRAY_BUFFER,mesh.size()*sizeof(V),mesh.data(),GL_STATIC_DRAW);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,p));glEnableVertexAttribArray(0);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,c));glEnableVertexAttribArray(1);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,n));glEnableVertexAttribArray(2);glVertexAttribPointer(3,2,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,uv));glEnableVertexAttribArray(3);glVertexAttribIPointer(4,4,GL_INT,sizeof(V),(void*)offsetof(V,boneIds));glEnableVertexAttribArray(4);glVertexAttribPointer(5,4,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,weights));glEnableVertexAttribArray(5);};configure(vao,vbo,cube);configure(sphereVAO,sphereVBO,sphereMesh);glGenVertexArrays(1,&textVAO);glGenBuffers(1,&textVBO);glBindVertexArray(textVAO);glBindBuffer(GL_ARRAY_BUFFER,textVBO);glBufferData(GL_ARRAY_BUFFER,0,nullptr,GL_STREAM_DRAW);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,p));glEnableVertexAttribArray(0);glVertexAttribPointer(1,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,c));glEnableVertexAttribArray(1);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,n));glEnableVertexAttribArray(2);glVertexAttribPointer(3,2,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,uv));glEnableVertexAttribArray(3);glVertexAttribIPointer(4,4,GL_INT,sizeof(V),(void*)offsetof(V,boneIds));glEnableVertexAttribArray(4);glVertexAttribPointer(5,4,GL_FLOAT,GL_FALSE,sizeof(V),(void*)offsetof(V,weights));glEnableVertexAttribArray(5);program=createProgram(vertexShaderSource.c_str(),fragmentShaderSource.c_str());if(program){modelLoc=glGetUniformLocation(program,"model");baseColorLoc=glGetUniformLocation(program,"baseColor");}}
