void sphere(glm::vec3 pos,glm::vec3 size,glm::vec3 color){glm::mat4 m(1);m=glm::translate(m,pos);m=glm::scale(m,size);glUniformMatrix4fv(modelLoc,1,GL_FALSE,glm::value_ptr(m));glUniform3fv(baseColorLoc,1,glm::value_ptr(color));glBindVertexArray(sphereVAO);glDrawArrays(GL_TRIANGLES,0,static_cast<GLsizei>(sphereMesh.size()));}
glm::vec3 localToWorld(const Zombie& z,float facing,glm::vec3 offset){float c=std::cos(facing),s=std::sin(facing);return z.p+glm::vec3(c*offset.x+s*offset.z,offset.y,-s*offset.x+c*offset.z);}
void drawZombieFigure(const Zombie& z,float facing){
    const bool alive=z.alive;const float gait=z.phase;
    glm::vec3 skin=z.hitFlash>0?glm::vec3(.95f,.82f,.38f):glm::vec3(.42f,.58f,.30f);
    glm::vec3 shirt=z.hitFlash>0?glm::vec3(.72f,.42f,.20f):glm::vec3(.24f,.29f,.18f);
    glm::vec3 dark=alive?glm::vec3(.16f,.20f,.12f):glm::vec3(.10f,.11f,.09f);
    if(!alive){
        sphere(z.p+glm::vec3(0,.24f,0),{1.05f,.34f,.58f},dark);
        sphere(z.p+glm::vec3(.48f,.27f,.02f),{.38f,.34f,.34f},{.30f,.38f,.23f});
        sphere(z.p+glm::vec3(-.35f,.18f,.38f),{.65f,.20f,.20f},dark);
        sphere(z.p+glm::vec3(-.20f,.15f,-.36f),{.62f,.18f,.20f},dark);
        return;
    }
    sphere(localToWorld(z,facing,{0,.99f,0}),{.62f,.82f,.42f},shirt);
    sphere(localToWorld(z,facing,{0,.61f,0}),{.65f,.13f,.44f},dark);
    sphere(localToWorld(z,facing,{0,1.43f,0}),{.20f,.22f,.20f},skin);
    sphere(localToWorld(z,facing,{0,1.69f,0}),{.40f,.43f,.36f},skin);
    for(float side:{-1.f,1.f}){
        float swing=std::sin(gait+(side>0?0.f:3.14159f));
        float armX=side*(.43f+.035f*swing);
        sphere(localToWorld(z,facing,{armX,1.18f,-.01f}),{.25f,.47f,.25f},skin);
        sphere(localToWorld(z,facing,{side*.48f,.77f,-.05f}),{.20f,.40f,.21f},skin);
        sphere(localToWorld(z,facing,{side*.49f,.51f,-.08f}),{.18f,.19f,.17f},skin);
        float legX=side*(.17f+.045f*swing);
        sphere(localToWorld(z,facing,{legX,.36f,.01f}),{.24f,.52f,.27f},dark);
        sphere(localToWorld(z,facing,{legX,.12f,-.025f}),{.19f,.30f,.21f},dark);
        sphere(localToWorld(z,facing,{legX,.055f,-.14f}),{.27f,.12f,.38f},{.12f,.10f,.08f});
        sphere(localToWorld(z,facing,{side*.115f,1.72f,-.31f}),{.075f,.075f,.035f},{1.f,.18f,.035f});
    }
}
glm::vec3 front(){float y=glm::radians(yaw),p=glm::radians(pitch);return glm::normalize(glm::vec3(cos(y)*cos(p),sin(p),sin(y)*cos(p)));}
void resize(GLFWwindow*,int w,int h){fbw=std::max(1,w);fbh=std::max(1,h);uiScale=std::max(1.f,float(fbw)/START_W);glViewport(0,0,fbw,fbh);}
void mouse(GLFWwindow*,double x,double y){if(!locked||paused||inventoryOpen||won||lost||!started)return;if(firstMouse){lastX=x;lastY=y;firstMouse=false;}yaw+=(x-lastX)*mouseSensitivity;pitch+=(lastY-y)*mouseSensitivity;lastX=x;lastY=y;pitch=glm::clamp(pitch,-82.f,82.f);}
