void setLock(bool v){locked=v;if(window)glfwSetInputMode(window,GLFW_CURSOR,v?GLFW_CURSOR_DISABLED:GLFW_CURSOR_NORMAL);firstMouse=true;}
int livingZombies(){return static_cast<int>(std::count_if(zombies.begin(),zombies.end(),[](const Zombie& z){return z.alive;}));}
