bool collectPickup();
void spawnZombies(int count=-1){if(count<0)count=WaveManager::zombieCountForLevel(wave);zombies.clear();const float spacing=std::max(1.35f,3.2f-.018f*wave);const int attempts=std::max(1800,count*360);for(int attempt=0;attempt<attempts&&static_cast<int>(zombies.size())<count;++attempt){float a=attempt*2.399963f,r=9.f+std::fmod(attempt*7.137f,28.f);glm::vec3 p(std::cos(a)*r,0,std::sin(a)*r);if(glm::distance(glm::vec2(p.x,p.z),glm::vec2(player.x,player.z))<10.f||worldBlocked(p.x,p.z,.45f))continue;bool crowded=false;for(const auto&z:zombies)if(glm::distance(glm::vec2(p.x,p.z),glm::vec2(z.p.x,z.p.z))<spacing){crowded=true;break;}if(crowded)continue;Zombie z;z.p=p;z.hp=WaveManager::zombieHealthForLevel(wave);z.speed=WaveManager::zombieSpeedForLevel(wave)+.10f*(attempt%4);z.damage=WaveManager::zombieDamageForLevel(wave);z.phase=attempt*1.7f;zombies.push_back(z);}if(static_cast<int>(zombies.size())<count)std::cerr<<"Spawn warning: placed "<<zombies.size()<<" / "<<count<<" zombies for level "<<wave<<'\n';}
void spawnPickups(){pickups={{glm::vec3(-8,0,8),PickupKind::Medkit,true},{glm::vec3(10,0,-12),PickupKind::Ammunition,true},{glm::vec3(-2,0,-13),PickupKind::Medkit,true},{glm::vec3(0,0,-23),PickupKind::Ammunition,true}};}
bool canClaimTreasure(){return wave>=3&&treasureUnlocked&&livingZombies()==0&&glm::distance(glm::vec3(player.x,0,player.z),treasurePos)<2.8f;}
void resetGame(){health=100;stamina=100;player={0,1.65f,10};jumpY=jumpV=0;grounded=true;weapons={Weapon{"PISTOL",12,48,12,50,.24f,45,1},Weapon{"SHOTGUN",6,24,6,18,.68f,25,7}};weaponIndex=0;killCount=0;wave=1;waveManager.reset();shotsFired=shotsHit=levelShotsFired=levelShotsHit=0;survivalTime=waveDelay=waveAnnouncement=meleeCooldown=reload=flash=damageFlash=noiseTimer=noiseRadius=0;lastShotHit=lastShotHeadshot=false;flashlightOn=true;inventoryOpen=false;settingsOpen=false;treasureUnlocked=false;treasureTaken=won=lost=paused=false;started=true;waveAnnouncement=2.5f;spawnZombies();spawnPickups();particles.clear();setLock(true);}
void key(GLFWwindow*,int k,int,int action,int){if(action!=GLFW_PRESS)return;auto adjustSensitivity=[&](float d){mouseSensitivity=glm::clamp(mouseSensitivity+d,.03f,.35f);};if(settingsOpen){if(k==GLFW_KEY_ESCAPE||k==GLFW_KEY_ENTER||k==GLFW_KEY_KP_ENTER){settingsOpen=false;return;}if(k==GLFW_KEY_LEFT||k==GLFW_KEY_MINUS)adjustSensitivity(-.01f);if(k==GLFW_KEY_RIGHT||k==GLFW_KEY_EQUAL)adjustSensitivity(.01f);return;}if(!started){if(k==GLFW_KEY_UP||k==GLFW_KEY_DOWN)menuSelection=(menuSelection+1)%3;if(k==GLFW_KEY_MINUS||k==GLFW_KEY_LEFT)adjustSensitivity(-.01f);if(k==GLFW_KEY_EQUAL||k==GLFW_KEY_RIGHT)adjustSensitivity(.01f);if(k==GLFW_KEY_ESCAPE)glfwSetWindowShouldClose(window,GLFW_TRUE);if(k==GLFW_KEY_ENTER||k==GLFW_KEY_KP_ENTER){if(menuSelection==0)resetGame();else if(menuSelection==1)settingsOpen=true;else glfwSetWindowShouldClose(window,GLFW_TRUE);}return;}if(paused&&(k==GLFW_KEY_UP||k==GLFW_KEY_DOWN)){pauseSelection=(pauseSelection+1)%4;return;}if(paused&&(k==GLFW_KEY_ENTER||k==GLFW_KEY_KP_ENTER)){if(pauseSelection==0){paused=false;setLock(true);}else if(pauseSelection==1)resetGame();else if(pauseSelection==2)settingsOpen=true;else glfwSetWindowShouldClose(window,GLFW_TRUE);return;}if(won||lost){if(k==GLFW_KEY_ENTER||k==GLFW_KEY_KP_ENTER||k==GLFW_KEY_ESCAPE)resetGame();return;}if(k==GLFW_KEY_ESCAPE){if(inventoryOpen){inventoryOpen=false;setLock(true);return;}if(!locked){paused=false;setLock(true);}else{paused=true;pauseSelection=0;setLock(false);}return;}if(k==GLFW_KEY_I&&!paused&&!won&&!lost){inventoryOpen=!inventoryOpen;setLock(!inventoryOpen);}if(k==GLFW_KEY_L&&!paused&&!inventoryOpen)flashlightOn=!flashlightOn;if(k==GLFW_KEY_1&&!paused&&!inventoryOpen){weaponIndex=0;reload=0;}if(k==GLFW_KEY_2&&!paused&&!inventoryOpen){weaponIndex=1;reload=0;}if(k==GLFW_KEY_E&&!paused&&!inventoryOpen&&!won&&!lost){if(!collectPickup()&&canClaimTreasure()){treasureTaken=true;won=true;setLock(false);}}}
bool clearingCell(int x,int z){if(std::abs(x)<7&&z<14&&z>-31)return true;if(glm::length(glm::vec2(x-27,z-18))<7)return true;if(glm::length(glm::vec2(x+27,z+8))<6)return true;return false;}
float treeX(int x,int z){return x+std::sin(x*1.37f+z*.63f)*2.15f;}
float treeZ(int x,int z){return z+std::cos(x*.41f-z*1.19f)*2.15f;}
bool clearingRock(float x,float z){return (std::abs(x)<5&&z<4&&z>-30)||glm::length(glm::vec2(x,z+22))<7||glm::length(glm::vec2(x-27,z-18))<8||glm::length(glm::vec2(x+27,z+8))<7;}
bool worldBlocked(float x,float z,float radius){if(std::abs(x)>WORLD_LIMIT-radius||std::abs(z)>WORLD_LIMIT-radius)return true;for(int tx=-36;tx<=36;tx+=8)for(int tz=-36;tz<=36;tz+=8){if(clearingCell(tx,tz))continue;float cx=treeX(tx,tz),cz=treeZ(tx,tz);if(std::abs(x-cx)<radius+.31f&&std::abs(z-cz)<radius+.31f&&glm::length(glm::vec2(x-cx,z-cz))<radius+.31f)return true;}for(int i=0;i<26;i++){float rx=std::sin(i*12.7f)*35,rz=std::cos(i*8.3f)*34;if(clearingRock(rx,rz))continue;if(glm::length(glm::vec2(x-rx,z-rz))<radius+.55f)return true;}for(float px:{23.5f,30.5f})for(float pz:{14.5f,21.5f})if(glm::length(glm::vec2(x-px,z-pz))<radius+.58f)return true;for(const glm::vec2 p:std::array<glm::vec2,3>{{{-30,-8},{-24,-8},{-27,-11}}})if(glm::length(glm::vec2(x-p.x,z-p.y))<radius+.65f)return true;if(z<-17.2f&&z>-26.8f&&std::abs(std::abs(x)-4.0f)<radius+.5f)return true;if(std::abs(z+17.7f)<radius+.35f&&std::abs(x)>1.6f-radius&&std::abs(x)<4.5f+radius)return true;if(std::abs(z+26.0f)<radius+.5f&&std::abs(x)<4.5f+radius)return true;return false;}
void moveZombieTowards(Zombie&z,glm::vec3 target,float stepTime){glm::vec3 d=target-z.p;d.y=0;float dist=glm::length(d);if(dist<.001f)return;glm::vec3 dir=d/dist;float travel=z.speed*stepTime;glm::vec3 step=dir*travel,trial=z.p+step;if(!worldBlocked(trial.x,trial.z,.40f))z.p=trial;else{glm::vec3 side(-dir.z,0,dir.x),left=z.p+side*travel,rightStep=z.p-side*travel;bool leftBlocked=worldBlocked(left.x,left.z,.40f),rightBlocked=worldBlocked(rightStep.x,rightStep.z,.40f);if(!leftBlocked&&!rightBlocked)z.p=glm::distance(left,target)<glm::distance(rightStep,target)?left:rightStep;else if(!leftBlocked)z.p=left;else if(!rightBlocked)z.p=rightStep;}}
int nearbyPickup(){int best=-1;float distance=2.2f;for(int i=0;i<(int)pickups.size();++i){if(!pickups[i].active||(pickups[i].kind==PickupKind::Medkit&&health>=100))continue;float d=glm::distance(glm::vec2(player.x,player.z),glm::vec2(pickups[i].p.x,pickups[i].p.z));if(d<distance){distance=d;best=i;}}return best;}
bool collectPickup(){int best=nearbyPickup();if(best<0)return false;auto&item=pickups[best];if(item.kind==PickupKind::Medkit)health=std::min(100.f,health+45.f);else{weapons[0].reserve=std::min(96,weapons[0].reserve+18);weapons[1].reserve=std::min(48,weapons[1].reserve+8);}item.active=false;return true;}
void completeReload(){auto&w=activeWeapon();int amount=std::min(w.magazine-w.ammo,w.reserve);w.ammo+=amount;w.reserve-=amount;reload=0;}
