    for(auto&z:zombies)z.alive=false;zombies[0].p={0,0,-8};zombies[0].hp=100;zombies[0].alive=true;player={0,1.65f,0};yaw=-90;pitch=-6.2f;weaponIndex=0;weapons[0].ammo=12;fireWait=0;shoot();expect(lastShotHit&&weapons[0].ammo==11&&zombies[0].hp==50,"pistol ray damages torso");shoot();expect(weapons[0].ammo==11,"pistol fire cooldown works");fireWait=0;shoot();expect(!zombies[0].alive&&killCount>0,"second pistol hit kills target");
