float speed=down(GLFW_KEY_LEFT_SHIFT)&&stamina>0?7.4f:4.5f;bool sprint=down(GLFW_KEY_LEFT_SHIFT)&&stamina>0;stamina=glm::clamp(stamina+(sprint?-27.f:18.f)*dt,0.f,100.f);glm::vec3 f=front(),flat=glm::normalize(glm::vec3(f.x,0,f.z)),right=glm::normalize(glm::cross(flat,{0,1,0})),move(0);if(down(GLFW_KEY_W))move+=flat;if(down(GLFW_KEY_S))move-=flat;if(down(GLFW_KEY_D))move+=right;if(down(GLFW_KEY_A))move-=right;if(glm::length(move)>0)move=glm::normalize(move)*speed*dt;
// circle obstacle collision; retain axis movement to slide along trees/ruins
for(int axis=0;axis<2;axis++){glm::vec3 trial=player;int coord=axis==0?0:2;trial[coord]+=move[coord];if(!worldBlocked(trial.x,trial.z,.38f))player=trial;}
