if(glm::length(move)>0)player.y=1.65f+jumpY+std::sin(glfwGetTime()*10.f)*.035f;else player.y=1.65f+jumpY;waveAnnouncement=std::max(0.f,waveAnnouncement-dt);auto waveEvent=waveManager.update(dt,livingZombies());if(waveEvent==WaveManager::Event::LevelCompleted){if(wave>=3)treasureUnlocked=true;health=std::min(100.f,health+12.f);weapons[0].reserve=std::min(96,weapons[0].reserve+6);weapons[1].reserve=std::min(48,weapons[1].reserve+3);}else if(waveEvent==WaveManager::Event::NextLevelStarted){wave=waveManager.level();levelShotsFired=levelShotsHit=0;spawnZombies();waveAnnouncement=2.5f;}
