int runAssetTests(){
    int ok=0,total=13;
    auto check=[&](bool pass,const char*name){std::cout<<(pass?"PASS ":"FAIL ")<<name<<'\n';ok+=pass?1:0;};
    const std::string saiga=asset("models/weapons/saiga_animated.glb");
    check(Model::validateAsset(asset("models/zombie/SK_SZombie_Variant_1.fbx"),1,1,60),"source zombie skeleton and T-pose clip");
    check(Model::validateAsset(asset("models/zombies/SZombie/SZombie_Variant_1/SM_SZombie_Variant_1.fbx"),1),"runtime static textured zombie mesh");
    check(Model::validateAsset(saiga,2,5,40),"skinned Saiga GLB and animation clips");
    check(Model::validateAsset(asset("models/hands/first_person_hands_rigged.glb"),2,0,40),"skinned first-person hands GLB");
    check(Model::validateAsset(asset("models/kenney/tree_detailed.glb"),3),"Kenney detailed broadleaf tree");
    check(Model::validateAsset(asset("models/kenney/tree_pineTallA_detailed.glb"),2),"Kenney detailed pine tree");
    check(Model::validateAsset(asset("models/kenney/tree_fat.glb"),2)&&Model::validateAsset(asset("models/kenney/tree_pineRoundA.glb"),2),"alternate canopy and pine models");
    check(Model::validateAsset(asset("models/kenney/rock_largeA.glb"),2)&&Model::validateAsset(asset("models/kenney/rock_largeB.glb"),2)&&Model::validateAsset(asset("models/kenney/rock_largeD.glb"),2),"three runtime rock variants");
    check(Model::validateAsset(asset("models/kenney/plant_bushDetailed.glb"),1)&&Model::validateAsset(asset("models/kenney/grass_large.glb"),1),"Kenney bush and grass props");
    check(Model::validateAsset(asset("models/ground_plane.obj"),1),"UV terrain plane");
    check(Model::validateAsset(asset("models/textured_cube.obj"),1),"UV stone-texture cube");
    bool clips=Model::hasAnimationClip(saiga,"Saiga_Idle")&&Model::hasAnimationClip(saiga,"Saiga_Walk")&&Model::hasAnimationClip(saiga,"Saiga_Fire")&&Model::hasAnimationClip(saiga,"Saiga_Reload_Fast")&&Model::hasAnimationClip(saiga,"Saiga_Reload_Full");
    check(clips,"Saiga idle walk fire and reload animation names");
    check(Model::validateImage(asset("textures/forest_ground_1k.jpg"))&&Model::validateImage(asset("textures/temple_stone_1k.jpg"))&&Model::validateImage(asset("models/zombie/T_SZombie_Variant_1_A_Albedo.png")),"ground, masonry, and zombie albedo images decode");
    std::cout<<"Asset checks "<<ok<<" / "<<total<<" passed.\n";return ok==total?0:1;
}
